challenges.reference_solution:
def total(items: list[float]) -> float:
    """Return the arithmetic sum of numeric items."""
    if not items:
        return 0.0
    return float(sum(items))

/**
 * Calculate final price after applying a percentage discount.
 * @param {number} price - Base price.
 * @param {number} discountPct - Discount percentage (0-100).
 * @returns {number} Final discounted price.
 */
export function calcDiscount(price, discountPct = 0) {
  if (discountPct <= 0) return price;
  if (discountPct >= 100) return 0;
  return Number((price - (price * discountPct) / 100).toFixed(2));
}
